class Solution:
    def maxOperations(self, nums: List[int], k: int) -> int:
        hmap = defaultdict(int)
        count = 0

        for i in range(len(nums)):
            complement = k - nums[i]
            if complement in hmap:
                hmap[complement] -= 1
                count += 1
                if hmap[complement] <= 0:
                    hmap.pop(complement)
            else:
                hmap[nums[i]] += 1

        return count
